var largestRectangleArea = function(heights) {
    const stack = []; // [earliestStart, height]
    let best = 0;
    const extended = heights.concat(0);

    for (let index = 0; index < extended.length; index++) {
        const height = extended[index];
        let start = index;
        while (stack.length && stack[stack.length - 1][1] > height) {
            const [poppedStart, oldHeight] = stack.pop();
            start = poppedStart;
            best = Math.max(best, oldHeight * (index - poppedStart));
        }
        stack.push([start, height]);
    }

    return best;
};

solution.python:
from typing import List

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        stack = []  # (earliest_start, height)
        best = 0

        for index, height in enumerate(heights + [0]):
            start = index
            while stack and stack[-1][1] > height:
                start, old_height = stack.pop()
                best = max(best, old_height * (index - start))
            stack.append((start, height))

        return best
